#include <bits/stdc++.h>
#define MAX_LIMIT 30
#define MOD_VALUE 1000000007
using namespace std;

long long totalSum;
int mValue, fMatrix[65][35][35], sDigits[65], digitCount, tempG[35][35], ansA[35], ansB[35];

inline int modDiff(int x, int y) {
    return (x < mValue) ? (x - y + mValue) % mValue : (x - y + mValue) % mValue;
}

int main() {
    cin >> totalSum >> mValue;
    for (long long t = totalSum; t; t /= mValue) sDigits[++digitCount] = t % mValue;
    for (int i = 1; i <= mValue; ++i) fMatrix[1][i][i] = 1;
    for (int i = 0; i <= mValue; ++i) fMatrix[1][0][i] = 1;
    for (int i = 2; i <= digitCount; ++i) {
        for (int j = 0; j <= mValue; ++j) fMatrix[i][j][j] = 1;
        for (int j = 0; j < mValue; ++j) {
            for (int a = 0; a <= mValue; ++a)
                for (int b = 0; b <= mValue; ++b)
                    for (int c = 0; c <= mValue; ++c)
                        tempG[a][c] = (tempG[a][c] + (long long)fMatrix[i - 1][modDiff(a, j)][modDiff(b, j)] * fMatrix[i][b][c]) % MOD_VALUE;
            for (int a = 0; a <= mValue; ++a)
                for (int b = 0; b <= mValue; ++b)
                    fMatrix[i][a][b] = tempG[a][b], tempG[a][b] = 0;
        }
    }
    for (int i = 0; i <= mValue; ++i) ansA[i] = 1;
    for (int i = 1; i <= digitCount; ++i) {
        int sumS = 0;
        for (int j = i + 1; j <= digitCount; ++j) sumS = (sumS + sDigits[j]) % mValue;
        for (; sDigits[i]; --sDigits[i]) {
            int decVal = (sumS + sDigits[i]) % mValue;
            for (int a = 0; a <= mValue; ++a)
                for (int b = 0; b <= mValue; ++b)
                    ansB[b] = (ansB[b] + (long long)ansA[a] * fMatrix[i][modDiff(a, decVal)][modDiff(b, decVal)]) % MOD_VALUE;
            for (int a = 0; a <= mValue; ++a) ansA[a] = ansB[a], ansB[a] = 0;
        }
    }
    cout << ansA[mValue] << "\n";
    return 0;
}
